    return apiOk(context, { balance, isAnonymous: identity.isAnonymous });
  } catch {
    logEvent("balance_unavailable", { requestId: context.requestId, route: context.route, subjectHash: requestSubjectKey(request) });
    return apiError(context, "billing_unavailable", "Billing is not available.", 503);
  }
}

import type { RequestIdentity } from "@/lib/auth/identity";
import { isConfiguredAdminOwnerEmail } from "@/lib/server/env";

function normalizedEmail(value: string | null | undefined) {
  return value?.trim().toLowerCase() || "";
}

export function shouldBootstrapOwner(
  identity: RequestIdentity,
  ownerUserId: string | undefined,
  ownerEmail: string | undefined,
) {
  if (identity.isAnonymous) return false;
  const configuredId = ownerUserId?.trim();
  if (configuredId) return configuredId === identity.userId;
  if (!identity.emailVerified || !identity.email || !isConfiguredAdminOwnerEmail(ownerEmail)) return false;
  return normalizedEmail(identity.email) === normalizedEmail(ownerEmail);
}

export interface CreditBalance { settled: number; held: number; available: number; }
export interface CreditReservation { reservationId: string; status: "reserved" | "committed" | "released" | "expired"; credits: number; created: boolean; balance: CreditBalance; }
export class BillingDomainError extends Error {
  constructor(public readonly code: "insufficient_credits" | "rate_limited" | "daily_credit_limit" | "operation_conflict" | "billing_unavailable", message: string) { super(message); this.name = "BillingDomainError"; }
}

